1	/**
2	 * Phase 3 E2E Validation Tests
3	 *
4	 * Validates Phase 3 acceptance criteria:
5	 * 1. Can add, edit, delete comments on an issue
6	 * 2. Can add, resolve, and delete blockages
7	 * 3. Sub-issues display in both the list (tree) and detail views
8	 * 4. Can create sub-issues with parentId pre-filled
9	 * 5. History timeline displays correctly
10	 * 6. Tag input works (add/remove)
11	 * 7. Parent can be set, changed, and cleared
12	 * 8. Blockage indicators show on issue list rows
13	 *
14	 * Also validates:
15	 * - Backend API endpoints (comments CRUD, blockages CRUD, history, next issue)
16	 * - Error handling and edge cases
17	 */
18	import { test, expect } from "@playwright/test";
