22	/**
23	 * Helper: navigate to page and wait for the issues API to respond.
24	 */
25	async function gotoAndWaitForIssues(
26	  page: import("@playwright/test").Page,
27	  url: string = "/"
28	) {
29	  const responsePromise = page.waitForResponse(
30	    (resp) => resp.url().includes("/api/issues") && resp.status() === 200,
31	    { timeout: 15000 }
32	  );
33	  await page.goto(url);
34	  await responsePromise;
35	}
36	
37	/**
38	 * Helper: navigate to issue detail page and wait for data.
39	 */
40	async function gotoIssueDetail(
41	  page: import("@playwright/test").Page,
42	  issueId: string
43	) {
44	  const responsePromise = page.waitForResponse(
45	    (resp) =>
46	      resp.url().includes(`/api/issues/${issueId}`) &&
47	      !resp.url().includes("/comments") &&
48	      !resp.url().includes("/blockages") &&
49	      !resp.url().includes("/history") &&
50	      resp.status() === 200,
51	    { timeout: 15000 }
52	  );
53	  await page.goto(`/issues/${issueId}`);
54	  await responsePromise;
55	}
