1	import { Hono } from "hono";
2	import { tracker } from "../utils/tracker.js";
3	
4	const issues = new Hono();
5	
6	// GET /api/issues — list issues with filters
7	issues.get("/", async (c) => {
8	  const status = c.req.query("status");
9	  const assignee = c.req.query("assignee");
10	  const tags = c.req.query("tags");
11	  const parentId = c.req.query("parentId");
12	  const search = c.req.query("search");
13	
14	  const params: Record<string, unknown> = {};
15	  if (status) params.status = status;
16	  if (assignee) params.assignee = assignee;
17	  if (tags) params.tags = tags.split(",");
18	  if (parentId !== undefined) {
19	    params.parentId = parentId === "null" ? null : parentId;
20	  }
21	
22	  const result = await tracker.list(params as Parameters<typeof tracker.list>[0]);
23	
24	  if ("result" in result && result.result !== undefined && typeof (result as { result: unknown }).result === "string" && "message" in result) {
25	    // It's an error
26	    throw Object.assign(new Error((result as { message: string }).message), result);
27	  }
28	
29	  // Server-side search filter on title substring
30	  let entries = result as import("agentrack").IndexEntry[];
31	  if (search) {
32	    const lowerSearch = search.toLowerCase();
33	    entries = entries.filter((e) => e.title.toLowerCase().includes(lowerSearch));
34	  }
35	
36	  return c.json(entries);
37	});
38	
39	// POST /api/issues — create a new issue
40	issues.post("/", async (c) => {
41	  const body = await c.req.json();
42	
43	  if (!body.title || typeof body.title !== "string" || body.title.trim() === "") {
44	    return c.json({ error: true, code: "VALIDATION_ERROR", message: "Title is required" }, 400);
45	  }
46	
47	  const result = await tracker.create({
48	    title: body.title.trim(),
49	    description: body.description ?? "",
50	    assignee: body.assignee ?? null,
51	    tags: body.tags ?? [],
52	    status: body.status,
53	    priority: body.priority,
54	    parentId: body.parentId ?? null,
55	    author: body.author,
