    );
    await page.getByRole("link", { name: "Users", exact: true }).click();
    await usersPromise;

    await expect(page).toHaveURL("/users", { timeout: 10000 });
    await expect(
      page.getByRole("heading", { name: "Users" })
    ).toBeVisible({ timeout: 10000 });
