test.describe("Frontend: Revoke User", () => {
  test("shows revoke confirmation dialog", async ({ page, request }) => {
    const name = `revoke-ui-${uniqueId()}`;
    await request.post(`${BASE}/api/users`, {
      data: { name },
    });

    await gotoUsersPage(page);

    // Wait for user to appear
    await expect(page.getByText(name)).toBeVisible({ timeout: 10000 });

    // Click Revoke button
    const revokeButtons = page.getByRole("button", { name: "Revoke" });
    await revokeButtons.first().click();

    // Confirmation dialog should appear
    await expect(
      page.getByRole("heading", { name: "Revoke User" })
    ).toBeVisible({ timeout: 5000 });
  });

  test("revokes user via confirm dialog and removes from list", async ({
    page,
    request,
  }) => {
    const name = `revoke-confirm-${uniqueId()}`;
    await request.post(`${BASE}/api/users`, {
      data: { name },
    });

    await gotoUsersPage(page);

    await expect(page.getByText(name)).toBeVisible({ timeout: 10000 });

    // Click Revoke in the user row
    await page.getByRole("button", { name: "Revoke" }).first().click();

    // Wait for dialog to appear
    await expect(
      page.getByRole("heading", { name: "Revoke User" })
    ).toBeVisible({ timeout: 5000 });

    // The dialog has a destructive "Revoke" button with "Revoking..." text when pending.
    // Use the dialog's locator to find the destructive confirm button.
    // Scope to the dialog's footer to avoid matching the row's Revoke button.
    const dialogRevokeBtn = page
      .locator('[role="dialog"]')
      .locator("button")
      .filter({ hasText: /^Revoke$/ })
      .first();

    await expect(dialogRevokeBtn).toBeVisible({ timeout: 5000 });

    // Set up the DELETE response listener BEFORE clicking confirm
    const deletePromise = page.waitForResponse(
      (resp) =>
        resp.url().includes("/api/users/") &&
        resp.request().method() === "DELETE" &&
        resp.url().includes(name),
      { timeout: 10000 }
    );
    await dialogRevokeBtn.click();
    await deletePromise;

    // Verify the user was actually deleted via direct API call
    const verifyRes = await request.get(`${BASE}/api/users`);
    const users = await verifyRes.json();
    const found = users.find((u: any) => u.name === name);
    expect(found).toBeUndefined();

    // Reload the page to verify the UI is consistent
    await gotoUsersPage(page);
    await expect(page.getByText(name)).not.toBeVisible({ timeout: 10000 });
  });

  test("cancels revoke without removing user", async ({ page, request }) => {
    const name = `revoke-cancel-${uniqueId()}`;
    await request.post(`${BASE}/api/users`, {
      data: { name },
    });

    await gotoUsersPage(page);

    await expect(page.getByText(name)).toBeVisible({ timeout: 10000 });

    // Click Revoke
    await page.getByRole("button", { name: "Revoke" }).first().click();

    // Cancel
    await page
      .getByRole("dialog")
      .getByRole("button", { name: "Cancel" })
      .click();

    // User should still be visible
    await expect(page.getByText(name)).toBeVisible({ timeout: 10000 });
  });
});

